const order = $json;
const money = (amount) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: order.currency, minimumFractionDigits: 0 }).format(amount);
// Names, items and everything read from the receipt image are untrusted: escape before HTML.
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const isReceipt = order.event === 'order.status_changed';
const shortId = order.id.slice(0, 8);

const rows = order.items
  .map((item) => `<tr><td>${esc(item.name)}</td><td align="center">${item.quantity}</td><td align="right">${money(item.unit_price * item.quantity)}</td></tr>`)
  .join('');

// AI receipt check (only present when the sub-workflow ran). It is a pre-check of the image,
// never proof of payment: only the money in the seller's account confirms it.
const check = order.receipt_check;
const VERDICTS = {
  match: { icon: '✅', label: 'Los datos del comprobante coinciden con el pedido', tag: '✅ Datos OK' },
  review: { icon: '⚠️', label: 'Revisa este comprobante con cuidado', tag: '⚠️ Revisar' },
  unverified: { icon: '❔', label: 'No se pudo verificar automáticamente, revísalo a mano', tag: '❔' },
};
const verdict = check ? VERDICTS[check.status] : null;

const subject = isReceipt
  ? `${verdict ? verdict.tag + ' ' : ''}Comprobante recibido — pedido #${shortId}`
  : `Nuevo pedido #${shortId} de ${order.buyer_name}`;

const intro = isReceipt
  ? `${esc(order.buyer_name)} subió el comprobante de pago del pedido <b>#${shortId}</b>. Revísalo y apruébalo o recházalo en Studio.`
  : `Tienes un pedido nuevo de <b>${esc(order.buyer_name)}</b>.`;

const receipt = isReceipt
  ? `<p>Número de transferencia: <b>${esc(order.transfer_number ?? '—')}</b></p>`
  : '';

const extracted = check?.extracted;
const aiBlock = verdict
  ? `<h3>${verdict.icon} Verificación automática</h3>
<p><b>${verdict.label}</b></p>
${check.reasons.length ? `<ul>${check.reasons.map((r) => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}
${extracted ? `<p style="color:#555">Leído del comprobante: monto ${extracted.amount != null ? money(extracted.amount) : '—'} · ref. ${esc(extracted.transfer_number ?? '—')} · ${esc(extracted.bank ?? 'banco no visible')} · ${esc(extracted.date ?? 'fecha no visible')} · destino ${esc(extracted.recipient ?? '—')} ${esc(extracted.recipient_account ?? '')}</p>` : ''}`
  : '';

const beforeApproving = isReceipt
  ? `<p style="background:#fff8e1;padding:8px"><b>Antes de aprobar:</b> abre tu banco o billetera (Nequi, Daviplata…) y confirma que el dinero ya entró a tu cuenta, por este monto y con esta referencia. Un comprobante es solo una imagen y puede ser falso o de otra compra; la verificación automática no lo descarta.</p>
<p style="color:#888;font-size:12px">La verificación la hace una IA y puede equivocarse: la aprobación final es tuya.</p>`
  : '';

const html = `<p>Hola ${esc(order.seller_name)},</p>
<p>${intro}</p>
<table cellpadding="6" style="border-collapse:collapse" border="1">
<tr><th align="left">Producto</th><th>Cant.</th><th align="right">Subtotal</th></tr>${rows}
<tr><td colspan="2"><b>Total</b></td><td align="right"><b>${money(order.total)}</b></td></tr>
</table>${receipt}${aiBlock}${beforeApproving}
<p style="color:#666">Mensaje automático de Libra.</p>`;

return { json: { to: order.seller_email, subject, html, order_id: order.id, kind: isReceipt ? 'receipt' : 'created', receipt_check: check?.status ?? null } };
